 57	export function parseTest4Arguments(argv, programName) {
 58	  const values = {
 59	    a: undefined,
 60	    b: undefined,
 61	    c: undefined,
 62	  };
 63	  const extras = [];
 64	
 65	  for (let index = 0; index < argv.length; index += 1) {
 66	    const token = argv[index];
 67	
 68	    if (token === '-h' || token === '--help') {
 69	      return {
 70	        kind: 'help',
 71	        text: formatHelp(programName),
 72	      };
 73	    }
 74	
 75	    if (token === '--') {
 76	      extras.push(...argv.slice(index + 1));
 77	      break;
 78	    }
 79	
 80	    const inline = extractInlineOption(token);
 81	    if (inline !== null) {
 82	      values[inline.key] = inline.value;
 83	      continue;
 84	    }
 85	
 86	    if (isSupportedOption(token)) {
 87	      const next = argv[index + 1];
 88	      if (next === undefined || next === '--' || isOptionLike(next)) {
 89	        return {
 90	          kind: 'error',
 91	          code: 2,
 92	          text: formatError(programName, `argument ${token}: expected one argument`),
 93	        };
 94	      }
 95	
 96	      values[token.slice(2)] = next;
 97	      index += 1;
 98	      continue;
 99	    }
100	
101	    extras.push(token);
102	  }
103	
104	  const missing = collectMissing(values);
105	  if (missing.length > 0) {
106	    return {
107	      kind: 'error',
108	      code: 2,
109	      text: formatError(
110	        programName,
111	        `the following arguments are required: ${missing.join(', ')}`,
112	      ),
113	    };
114	  }
115	
116	  if (extras.length > 0) {
117	    return {
118	      kind: 'error',
119	      code: 2,
120	      text: formatError(programName, `unrecognized arguments: ${extras.join(' ')}`),
121	    };
122	  }
123	
124	  return {
125	    kind: 'ok',
126	    values,
127	  };
128	}

